pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address caller, bytes32 digest, bytes32 r, bytes32 s) internal {
        bool approvedBefore;
        try c.approvedToLog(caller) returns (bool __r) { approvedBefore = __r; } catch { return; }
        bool reverted;
        bool result;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool ok) {
            result = ok;
            reverted = false;
        } catch {
            reverted = true;
            result = false;
        }
        assertTrue(!reverted && result == approvedBefore);
    }

    function testFuzz_run(address caller, bytes32 digest, bytes32 r, bytes32 s) public {
